import { apiRequest } from './apiClient'

export const customerService = {
  /**
   * Fetch unique customers aggregated from database orders
   */
  async fetchCustomers() {
    try {
      const res = await apiRequest('/customers')
      if (res && res.data) {
        return res.data
      }
      return []
    } catch (err) {
      console.warn('⚠️ [CUSTOMER:SERVICE] Failed to fetch customers from API:', err.message)
      return []
    }
  },

  /**
   * Send single customer offer email or broadcast to all customers
   * @param {Object} payload
   * @param {'single'|'all'} payload.target
   * @param {string} [payload.recipientEmail]
   * @param {string} [payload.recipientName]
   * @param {string} payload.subject
   * @param {string} [payload.headline]
   * @param {string} [payload.offerBadge]
   * @param {string} [payload.discountCode]
   * @param {string} payload.messageBody
   * @param {string} [payload.buttonText]
   * @param {string} [payload.buttonLink]
   */
  async sendCustomerEmail(payload) {
    console.log('📤 [CUSTOMER:SERVICE] Sending email request:', payload)
    const res = await apiRequest('/customers/send-email', {
      method: 'POST',
      body: payload
    })
    return res
  }
}
